function lxNotes(){const L=S.layout,o=S.l20||{},f=x=>Math.round(x).toLocaleString("en-US"),pc=(a,b)=>(100*a/Math.max(1,b)).toFixed(1)+"%",NN=S.N.toLocaleString("en-US");
 if(L==="chaosgap"&&o.cg){const c=o.cg;return {chaosgap:`Only the primes are drawn, from 7 on. A point starts in the middle and at every prime jumps half-way to one of three corners, chosen by the gap g from the prime before: the top for g ≡ 0 (mod 6), bottom left for g ≡ 2, bottom right for g ≡ 4; the prime is drawn where the point lands (the chaos game). Gaps drawn at random would paint Sierpinski's triangle. The primes paint a thin dust instead: a gap ≡ 2 leads from a prime ≡ 5 (mod 6) to a prime ≡ 1, and a gap ≡ 4 leads back, so the 2s and 4s must take turns, with any number of 0s between them (${f(c.bad)} exceptions here). Of the 3⁸ = 6,561 words of 8 gap classes in a row only ${f(c.words)} occur up to ${NN}; the rule allows 511. Each step has two choices, not three (0, or the one step that is allowed), so the dust has dimension 1, against 1.585 for the triangle. The classes are used ${f(c.cnt[0])}, ${f(c.cnt[1])} and ${f(c.cnt[2])} times (0, 2, 4): the 2s and 4s differ by at most one. Zoom in: every branch repeats the whole picture.`};}
 if(L==="chaoslane"&&o.cl){const c=o.cl,r=i=>(c.T[i]/(c.tot/16)).toFixed(2),nm=i=>`${c.U[Math.floor(i/4)]} → ${c.U[i%4]}`;return {chaoslane:`Only the primes are drawn. The four corners are the remainders ${c.U.join(", ")} that a prime can leave mod ${c.M} (top left, top right, bottom left, bottom right). At every prime the point jumps half-way to the corner of its remainder: the quarter a prime lands in is its own remainder, the quarter of that quarter the remainder of the prime before it, and so on, so every word of consecutive remainders has its own small square. Independent remainders would fill the square evenly. They do not: a prime repeats the remainder of the prime before it ${pc(c.rep,c.tot)} of the time, not 25% (the bias of Lemke Oliver and Soundararajan, 2016), because a repeat needs a gap that is a multiple of ${c.M}; so the small squares that point at their own corner are thin, at every scale. The rarest step is ${nm(c.mn)} (${r(c.mn)} times an even share), the commonest ${nm(c.mx)} (${r(c.mx)}). Period P chooses the modulus: 5, 8, 10 or 12.`};}
 if(L==="returnmap"&&o.rm){const r=o.rm;return {returnmap:`Only the primes are drawn, from 7 on, each in the cell of its two gaps: the gap before it across and the gap after it upwards, both from 2 to ${r.G}. A cell fills from its centre, so its size shows how many primes have that pair of gaps (${f(r.shown)} of ${f(r.tot)} primes fit). Two cells in nine stay empty: after a gap ≡ 2 (mod 6) the prime is ≡ 1 (mod 6), so the next gap cannot be ≡ 2, and after a gap ≡ 4 it cannot be ≡ 4 (${f(r.forb)} exceptions here; the only one is 3, 5, 7, left out). The fullest cell is (${r.ba}, ${r.bb}), with ${f(r.bc)} primes. On the diagonal the two gaps are equal, three primes in arithmetic progression: that happens ${f(r.eq)} times, where the same gaps in random order would give ${f(r.eqE)} (${(r.eq/Math.max(1,r.eqE)).toFixed(2)} times as many), because an equal pair must be a multiple of 6.`};}
 if(L==="dejavu"&&o.dj){const d=o.dj,rows=d.cnt.map((c,i)=>i+": "+f(c)).join(", ");return {dejavu:`Row L holds the primes after which the next L gaps copy the gaps after ${d.st}, the first gaps of all (p grows to the right; row 0 at the top). The start prime is the period P when P is a prime from 5 on, otherwise 11. Counts up to ${NN}: ${rows}. The longest copy here has ${d.mx} gaps: ${f(d.first[d.mx])} starts ${d.mx+1} primes spaced exactly like the first ${d.mx+1} primes from ${d.st} on. A copy can only go so far: the ${d.adm+1} primes from ${d.st} on leave every remainder taken for some small prime, so one of any ${d.adm+1} numbers spaced like them is a multiple of it; the longest stretch that can come back has ${d.adm} primes (${d.st} to ${f(d.admLast)}). The start of the primes is the survivors of a wheel, and a wheel repeats: the primes copy their own beginning as often as the Hardy–Littlewood count of that pattern allows, and row 2 is ${(d.cnt[1]/Math.max(1,d.cnt[2])).toFixed(1)} times thinner than row 1.`};}
 if(L==="goldfirst"&&o.gf){const g=o.gf;return {goldfirst:`Each even number n from 6 on sits in the row of the smallest prime p for which n − p is prime too: row 1 is p = 3, row 2 is p = 5, and so on (n grows to the right; light means a multiple of 6, not prime). Row p is empty at the multiples of p, where n − p is one too: no multiple of 6 sits in row 1. Elsewhere a multiple of 3 succeeds twice as often per try (Hardy and Littlewood), so the light dots need ${g.m3.toFixed(2)} primes on average and the others ${g.m0.toFixed(2)}; ${pc(g.r0,g.c0)} of the others succeed at once, with 3. The search never takes long: the worst case up to ${NN} is n = ${f(g.rn)}, which needs the ${g.K+1}th odd prime, ${f(g.rp)}. If every try were an independent coin, the worst case up to N would grow like ln(N/2)·ln N/(2C₂) = ${f(g.cap)} tries here; the record stays below it, as the largest prime gaps stay below Cramér's ln²p.`};}
 if(L==="mirror"&&o.mi){const m=o.mi,ds=[];for(let d=1;d<m.cnt.length;d++)if(m.tot[d]&&(d<m.D||m.full))ds.push(`${d}: ${f(m.cnt[d])} (${f(m.prd[d])})`);return {mirror:`Number n sits at its own size across and at its digits reversed upwards, written in base B = P = ${m.B}; the height is the reversed number as a fraction of ${m.B}^d for d digits. Blue is a prime, green a prime whose reversal is prime as well (palindromes included). Counting is not all there is to it: n and its reversal have the same digit sum, so they leave the same remainder mod B − 1 = ${m.B-1}, and remainders that differ at most by sign mod B + 1 = ${m.B+1}; a prime's reversal is therefore never divisible by a prime factor of ${m.B*m.B-1} (except that factor itself), and it avoids the factors of ${m.B} exactly when the first digit of n does. That makes a reversal ${m.K2.toFixed(2)} times as likely to be prime as a number of its size, once its last digit allows it. Reversible primes by number of digits, with that prediction in brackets: ${ds.join(", ")}.`+(m.QS.length?` The counts stray from it by a few per cent, and more in a small base, because a prime q with a short period in base ${m.B} also ties n to its reversal while the digits are few: among the primes here the reversal is a multiple of `+m.QS.map((q,i)=>`${q} for ${pc(m.qh[i],m.qn[i])} (an even share is ${(100/q).toFixed(1)}%)`).join(", ")+".":"")+` Try P = 2, 10 and 12.`};}
 if(L==="survivors"&&o.sv){const v=o.sv;return {survivors:`Every number with a prime factor up to y = P = ${v.y} is thrown out (the primes up to ${v.y} too) and the rows close up: ${f(v.surv)} of the numbers up to ${NN} survive, in rows of the chosen width, and ${f(v.pc)} of them are prime (${pc(v.pc,v.surv)}). With a small y the next primes still show, as a rhythm: for y = 7 try a width of 48 (the 48 survivors of every 210 numbers), where a column is one remainder mod 210 and the multiples of 11 are every 11th dot of it, the multiples of 13 every 13th. With a large y nothing is left to see, and that is the point: among the survivors, primes behave like the flips of a coin. Two primes in a row happen ${f(v.pairs)} times here, ${(v.pairs/Math.max(1e-9,v.pe)).toFixed(3)} times what coin flips with the same local chance would give. The chance itself, 1/(ln n·∏(1 − 1/q)) over the primes q up to y, predicts ${f(v.pred)} primes: ${(v.pc/Math.max(1e-9,v.pred)).toFixed(3)} times that are found. That ratio is 1/(e^γ·ω(u)) with u = ln n/ln y and ω Buchstab's function; for large numbers it is exactly 1 where y = n^0.4027, about ${f(v.fair)} for ${NN} (here y = N^${v.c.toFixed(3)}): the deepest sieve whose coin needs no correction.`};}
 if(L==="scales"&&o.sc){const c=o.sc,pick=[0,3,6,9,12,c.K-1].filter((k,i,a)=>k<c.K&&a.indexOf(k)===i);return {scales:`Each number n is the middle of a window with H numbers on either side, H = 1, 2, 4, …, ${f(2**(c.K-1))}, dealt out evenly over the numbers (row k: H = 2^k, the top row H = 1). Its height in the row is the number of primes in the left half minus the number in the right half (less the little that the thinning of the primes explains), divided by what coin flips would give, √(2H/ln n); the band is drawn three such units up and down. If primes were coin flips with chance 1/ln n, every row would be equally wide. The rows narrow downwards: the mean square is `+pick.map(k=>`${c.v[k].toFixed(2)} for H = ${f(2**k)}`).join(", ")+` (coins: ${c.coin.toFixed(2)} in every row). The primes share themselves out more evenly than chance, and the more so the longer the window: the fall is a straight line in ln H, ${c.slope.toFixed(3)} per doubling of H here (rows H = 8 to ${f(2**(c.K-2))}), where the formula of Montgomery and Soundararajan (2004) gives ln 2/ln n ≈ ${c.ms.toFixed(3)}: near H = √n about half the variance of a coin is gone. Small windows feel only the sieve of the small primes; in long windows the same line comes from the spacing of the zeta zeros, and no sieve with coin flips above it can copy it. The long rows wave slowly because neighbouring windows overlap.`};}
 if(L==="atlas"&&o.at){const a=o.at;return {atlas:`Here a dot is not the number n but a value of a polynomial: each column is one polynomial m² + m + A, for the ${f(a.Cn)} odd A from 1 to ${f(a.maxA)}, and row m (downwards, m = 0 to ${a.R-1}) holds its value; light means that value is prime. Every straight line of the Ulam spiral, the Klauber triangle and the other square layouts is a column of this atlas. The columns are sorted, the richest on the left: `+a.top.map(o=>`A = ${o.A} (${o.c} primes, class number ${o.h})`).join(", ")+`; the poorest is A = ${a.last.A} with ${a.last.c}. Euler's A = 41 has ${a.e41?a.e41.c:"?"} and starts with 40 primes in a row. Why a column is rich is one number: its discriminant D = 1 − 4A has a class number h(D), the number of classes of quadratic forms, and a small h for the size of D means that many small primes never divide the polynomial. Over the ${f(a.k)} columns from A = 3 on, ln(primes in the column) and ln(√|D|/h) have correlation ${a.cor.toFixed(3)}. The columns with h = 1 are A = ${a.h1.join(", ")}; there are no others (Heegner, Baker, Stark), and the last gives D = −163 = 1 − 4·41. The pink dots are not shown here.`};}
 if(L==="spectrum"&&o.sp){const s=o.sp,nm=s.kind===1?"the Riemann zeta function":s.kind===4?"L(s, χ₋₄), the character of the race mod 4":s.kind===12?"L(s, χ₁₂), the character of the two lanes mod 12 (+1 for ±1, −1 for ±5)":s.kind===8?"L(s, χ₈) (+1 for ±1, −1 for ±3 mod 8)":`L(s, χ), χ the squares character mod ${s.kind} (+1 for a square, −1 for a non-square)`;
  return {spectrum:`Here the dots are only ink: the picture is a spectrum, read off the primes up to ${NN} and nothing else. Take the walk ${s.kind===1?"ψ(x) − x, where ψ adds ln p at every prime power":"that adds χ(p)·ln p at every prime power, the prime race of that character"}, divide by √x, take off its level and the part that dies out like 1/√x, and ask which waves cos(t·ln x) it is made of; across is the height t from 0 to ${s.tmax}, upwards the strength of that wave. The peaks stand at the zeros of ${nm} on the critical line: here at t = ${s.pk.map(t=>t.toFixed(2)).join(", ")}`+(s.zs.length?`; the zeros are at ${s.zs.filter(z=>z<s.tmax).map(z=>z.toFixed(2)).join(", ")} (light columns)`:"")+`. A peak is about ${s.res.toFixed(1)} wide, since the walk spans only ${(4*Math.PI/s.res).toFixed(1)} units of ln x, so zeros closer than that merge. The period P chooses the character: 1 or 2 for the zeta function, 4, 8 or 12, or a prime P for the squares mod P; try 19 and 43, whose lowest zeros (1.52 and 0.84) are so low that the non-squares lose the lead for long stretches. The pink dots are not shown here.`};}
 if(L==="parity"&&o.pa){const p=o.pa,sg=x=>(x<0?"−":"")+f(Math.abs(x));return {parity:`Every prime stands on the line of its band (${f(p.W2)} primes per band, set by the width). The numbers up to the next prime are sorted by one question: is the number of their prime factors, counted with repeats, even or odd? Even goes above the line, odd below (12 = 2·2·3 has three: below). No sieve can answer that question: a sieve cannot tell an even number of prime factors from an odd one (the parity problem). Above the lines stand ${f(p.U)} numbers and below ${f(p.D)}. The difference is exactly π(N) + L(N) − 1 = ${f(p.m)} ${p.L<0?"−":"+"} ${f(Math.abs(p.L))} − 1 (${p.ok?"checked":"NOT equal"}), with L Liouville's sum: every prime, a number with one factor, is balanced by one extra number above. ${pc(p.hi,p.m)} of the towers are taller above and ${pc(p.lo,p.m)} taller below (none is level from 3 on: a gap holds an odd number of numbers). The first number after a prime leans the other way: over the odd primes, p + 1 above minus p + 1 below is ${sg(p.f1)}, and that running difference is below zero at ${pc(p.neg,p.np)} of the primes (the last number before a prime, p − 1: ${sg(p.f0)}; coin flips would stray by about ${f(Math.sqrt(p.np))}). An exact identity sorts the first one: write p + 1 = k·m² with k square-free; then p + 1 goes above or below with k alone. So the primes 2m² − 1 (${f(p.kc[0])} here), 3m² − 1 (${f(p.kc[1])}) and 5m² − 1 (${f(p.kc[2])}) all pull down and the primes 6m² − 1 (${f(p.kc[3])}) pull up. The lean is the expected one. The expected numbers of primes k·m² − 1 (Bateman and Horn), taken with their signs over all square-free k up to 3,000, add up to ${sg(p.e1)}; for p − 1, with the primes k·m² + 1, to ${sg(p.e0)}. The layout “Lean by distance” tests this rule for 3,000 distances at once.`};}
 if(L==="classrows"&&o.cr2){const c=o.cr2,sh=c.pcn.map(v=>(100*v/Math.max(1,c.po)).toFixed(1)+"%");return {classrows:`Row k holds the numbers n whose class number h(−4n) is divisible by 2^k and by no higher power of 2 (row 0, the top: odd class numbers). The class number counts the reduced forms ax² + 2bxy + cy² with ac − b² = n; the page counts them one by one and never divides n by anything. Yet the rows know the factors: by Gauss's theory of genera a number with r odd prime factors lies in row r − 1 or deeper (row r when n ≡ 1 or 2 mod 4; ${f(c.badG)} exceptions here). So the primes float. The top row holds ${f(c.cnt[0])} numbers, ${f(c.pcn[0])} of them prime: every prime ≡ 3 (mod 4), and besides them only 1, 2, 4 and odd powers of such primes (${c.odd0.join(", ")}, …). Row 1 holds the primes ≡ 5 (mod 8), and every prime ≡ 1 (mod 8) lies deeper (${f(c.bad8)} exceptions). Of those, the ones in row 3 or deeper are exactly the primes x² + 32y² (${f(c.c32)} of ${f(c.c18)}; ${f(c.bad32)} exceptions; Barrucand and Cohn, 1969). Each row holds half as many primes as the row above: ${sh.join(", ")}. For rows 0 to 2 a remainder mod 8 decides and for row 3 one quadratic form; from row 4 on no such rule is known, only the halving. The largest class number here is ${f(c.mxh)}, for n = ${f(c.mxn)}. The odd exponents by row: ${Array.from(c.ex,(v,i)=>(i)+": "+(v||0)).join(", ")}; they follow their remainders mod 8.`};}
 if(L==="lean"&&o.le){const e=o.le,sg=x=>(x<0?"−":"")+f(Math.abs(x)),g=d=>e.grp.find(x=>x.d===d);return {lean:`A dot is a distance here. For every distance n from 1 to ${f(e.K)} the page takes the ${f(e.np)} primes p up to ${NN} and asks of p + n: is the number of its prime factors, counted with repeats, even or odd? The height of dot n is the count even minus odd; light dots are prime distances. Coin flips would give heights around 0 with a spread of ${f(Math.sqrt(e.np))}; the spread found is ${f(e.a.sdS)}. The extra is a pattern, and it can be computed in advance. Write p + n = k·m² with k square-free; then k alone decides even or odd, so the height is a signed count of the primes of the form k·m² − n, plus for a k with an even number of prime factors and minus for an odd one. The expected number of such primes is known for each polynomial (Bateman and Horn); summed over all square-free k up to 3,000 it gives the expectation, and that is the place of the dot from left to right. So a dot on the green line was predicted exactly. The dots follow the line: slope ${e.a.slope.toFixed(2)} ± ${e.a.err.toFixed(2)} (1 is a perfect prediction), correlation ${e.a.cor.toFixed(2)}, and what is left after the prediction has a spread of ${f(e.a.sdR)} (coin flips: ${f(Math.sqrt(e.np))}). The sum stops at k = 3,000; a longer one changes little (to k = 30,000, for N = 500,000 and distances up to 1,500: slope 1.05). The strongest part goes by what n shares with 30: distances that are multiples of 30 lean odd (mean ${sg(g(30).s)}, expected ${sg(g(30).b)}), multiples of 6 that are not multiples of 5 also (${sg(g(6).s)}, expected ${sg(g(6).b)}), odd multiples of 3 without 5 lean even (${sg(g(3).s)}, expected ${sg(g(3).b)}), and distances that share nothing with 30 stay near the middle (${sg(g(1).s)}, expected ${sg(g(1).b)}). The number right after a prime, n = 1: ${sg(e.s1)}, expected ${sg(e.b1)}. The numbers before a prime, p − n, follow the same rule with the primes k·m² + n (for n = 1 the count is ${sg(e.sm1)}). The rule that even and odd balance out along the primes is an open conjecture (Chowla's, for shifted primes); this lean is the next, smaller term, and it is of the order √N / ln N.`};}
 if(L==="sqwalk"&&o.sq){const q=o.sq,Qs=f(q.Q);return {sqwalk:`One prime stands for the whole line: Q = ${Qs}${q.isExp?", a Mersenne exponent":""} (the period P picks the prime; below 100 the page takes the largest Mersenne exponent ≡ 3 (mod 4) up to N). Every smaller number n takes one step: up if n is a square modulo Q (n ≡ x² for some x), down if not. Each dot is the height after the step of n; light dots are prime n. Half of the numbers are squares, so the walk ends at 0, at the right. The step of a product is the product of the steps, so the steps at the primes fix the whole walk (${f(q.pu)} primes step up and ${f(q.pd)} down; the first step down is at ${f(q.lnr)}). `+(q.m3?`Q ≡ 3 (mod 4), so the walk is its own mirror image, and two heights are exact. In the middle, at Q/2, it stands at ${f(q.mid)} = ${2-q.two} × ${f(q.h)}, and its mean height is ${f(q.ar)} / ${Qs} = ${f(q.ar/q.Q)}: both are the class number h(−${Qs}) = ${f(q.h)}, the number of reduced quadratic forms of discriminant −${Qs}, which the page counts separately (${q.mid===(2-q.two)*q.h&&q.ar===q.Q*q.h?"both checked":"NOT equal"}). The factor in the middle is 1 for Q ≡ 7 (mod 8) and 3 for Q ≡ 3 (mod 8) (Dirichlet). `:`Q ≡ 1 (mod 4), so the second half undoes the first: the walk returns to 0 in the middle (height there: ${f(q.mid)}). At a quarter of the way it stands at ${f(q.qt)}, half of the class number h(−4·${Qs}) = ${f(q.h)}, which the page counts separately (${2*q.qt===q.h?"checked":"NOT equal"}). `)+`The walk is at or above the line for ${pc(q.pos0,q.Q-1)} of the numbers; highest point ${f(q.mx)}, lowest ${q.mn<0?"−":""}${f(Math.abs(q.mn))}. Nothing is divided here: whether n is a square mod Q says nothing about the factors of n.`};}
 if(L==="curve"&&o.cu){const c=o.cu,mn=x=>String(x).replace("-","−");return {curve:`Every prime p gets a height from a curve, with no division. The curve is ${c.eq} (conductor ${f(c.cd)}, rank ${c.rank}; the period P picks 11, 37, 389 or 5077 for rank 0, 1, 2 or 3, and 27 or 32 for two curves with extra symmetry). The page counts the pairs (x, y) modulo p that satisfy the equation. About p of them do; the surplus is a = p − (the count), and Hasse proved that |a| ≤ 2√p. Top: each of the ${f(c.np)} odd primes up to ${f(c.Lm)}, from left to right, at height a / 2√p between −1 (bottom) and 1 (top). `+(c.cd===27||c.cd===32?`This curve has extra symmetry, so half of the primes stand exactly on the middle line with a = 0 (${f(c.zero)} of ${f(c.np)}; they are the primes ≡ ${c.cd===32?"3 (mod 4)":"2 (mod 3)"}), and the others pile up near the two edges. `:`The heights fill a half circle: dense in the middle, thin at the edges (the Sato–Tate law, proved in 2011). In eight equal bands from bottom to top the shares are ${c.hb.map(v=>(100*v/c.np).toFixed(1)).join(", ")}%; the half circle gives ${c.sb.map(v=>(100*v).toFixed(1)).join(", ")}% (largest gap between the two distributions ${c.ks.toFixed(3)}; chance alone stays below ${(1.36/Math.sqrt(c.np)).toFixed(3)} in 95% of cases). Only ${f(c.zero)} primes stand exactly on the middle line. `)+`Bottom, in green: the running sum of a·ln p / p against ln p, drawn with the composite numbers. Up and down nearly cancel, but not quite: the sum drifts in a straight line, and its slope tells how many independent rational points the curve has (its rank r): the slope should be ½ − r. Here the sum ends at ${mn(c.run.toFixed(2))}, which is ${mn(c.tl.toFixed(2))} × ln ${f(c.Lm)} (slope from 1,000 on: ${mn(c.slope.toFixed(2))}); ½ − r = ${mn((0.5-c.rank).toFixed(1))}. So the primes lean down a little, in proportion to the rank. That link between counts modulo primes and rational points is the conjecture of Birch and Swinnerton-Dyer; it is open in general, and proved when the rank read off this way is 0 or 1.`};}
 if((L==="famplus"||L==="famminus")&&o.fa){const a=o.fa,pl=a.sh>0,top=a.fl.slice().sort((x,y)=>y.n-x.n),shr=top.slice(0,6).map(x=>`${f(x.q)}: ${pc(x.n,a.tot-1)}`).join(", "),exs=top.filter(x=>a.eb[x.q]).map(x=>`${f(x.q)}: ${a.eb[x.q]} (${(a.ex*x.n/(a.tot-1)).toFixed(1)} expected)`).join(", "),txt=`Every odd prime q points to a smaller prime: the largest prime factor of q ${pl?"+":"−"} 1. Follow the pointers and you always end at 2. The last prime before 2 is one whose q ${pl?"+":"−"} 1 is a power of 2, and that is a ${pl?"Mersenne prime (3, 7, 31, 127, 8,191, …)":"Fermat prime (3, 5, 17, 257 and 65,537 are the only ones known)"}. So every odd prime belongs to the family of exactly one ${pl?"Mersenne":"Fermat"} prime. The picture is that family tree for the ${f(a.tot)} primes up to ${NN}: 2 at the top, the ${a.fl.length} founders below it (green), and every prime one band below the prime it points to; inside a band the primes run from small at the top to large at the bottom. Each family is as wide as its number of members, with a gap between families; light and dark mark the branches of the founders' children (here light does not mean prime: every dot is a prime, and the other numbers are hidden). The families by size: ${shr}. `+(pl?`These shares barely move with N (computed separately: the family of 3 holds 68.7%, 69.1%, 69.1% and 69.1% of the primes up to 10⁴, 10⁵, 10⁶ and 10⁷); no formula for them is known to us. `:`These shares barely move with N (computed separately: the family of 3 holds 52.4%, 53.3%, 53.0% and 52.9% of the primes up to 10⁴, 10⁵, 10⁶ and 10⁷); no formula for them is known to us. `)+`The longest chain has ${a.mxd} steps to 2 and starts at ${f(a.mxq)}; primes per band, from the founders down: ${a.dc.slice(1).map(v=>f(v||0)).join(", ")}. The ${a.ex} odd Mersenne exponents up to N by family: ${exs}; they follow the sizes of the families.`;return {[L]:txt};}
 if((L==="expclass"||L==="per10"||L==="per2")&&o.cb){const b=o.cb,sh=c=>100*c.up/Math.max(1,c.up+c.dn),srt=b.cl.map((c,i)=>({...c,fk:b.fk[i],s:sh(c)})).sort((x,y)=>y.s-x.s),avg=b.tu/b.tn,lst=a=>a.map(c=>`${c.r}: ${c.s.toFixed(1)}%`).join(", ");
  if(L==="expclass"){const wsum=srt.reduce((a,c)=>a+c.s,0),ex=c=>(b.nex*c.s/wsum).toFixed(1),row=c=>`${c.r} (first possible factor ${2*c.fk}p + 1): ${c.s.toFixed(1)}%, exponents ${c.ex} (${ex(c)} expected)`;
   return {expclass:`The puzzle method, applied to the exponents: check them modulo small numbers. Every prime p up to ${NN} stands in the column of its remainder mod ${b.M} (the period P; multiples of 4). It goes up, light, when 2^p − 1 has no factor 2kp + 1 with k ≤ ${b.K}, and down, dark, when it has one; ${pc(b.tu,b.tn)} go up. Every Mersenne exponent goes up. The columns are not equal, and the reason is a chain of small steps. A factor of 2^p − 1 is 2kp + 1, it is ≡ ±1 (mod 8), and it is prime; so for each remainder of p some k can never occur, because 2kp + 1 would be ≡ 3 or 5 (mod 8) or a multiple of 3, 5, …. A small k that can occur is a likely factor: 2kp + 1 divides 2^p − 1 about once in k times when it is prime. The remainder that allows k = 1 is hit hardest. Columns from best to worst: ${srt.length<=8?srt.map(row).join("; "):srt.slice(0,4).map(row).join("; ")+"; …; "+srt.slice(-4).map(row).join("; ")}. The known rule (Wagstaff) only separates p ≡ 1 from p ≡ 3 (mod 4); the remainder mod 3 matters as much: for p ≡ 7 (mod 12) the first possible factor is 10p + 1, for p ≡ 11 (mod 12) it is 2p + 1. The expected numbers of exponents are the ${b.nex} odd exponents up to N shared out by these survival rates; with so few exponents the counts can only be compared roughly.`};}
  const pure1=srt.filter(c=>c.dn===0&&c.up>0).map(c=>c.r),pure0=srt.filter(c=>c.up===0&&c.dn>0).map(c=>c.r),mix=srt.filter(c=>c.up>0&&c.dn>0);
  return {[L]:`One remainder does all the work. Every prime p up to ${NN} stands in the column of its remainder mod ${b.M} (the period P${L==="per10"?"; below 20 it is read as 40":"; multiples of 8, otherwise 24"}). It goes up, light, when the period of 1/p in base ${b.base} is even, and down, dark, when it is odd${b.base===2?" (even means: p divides some number 2^n + 1; odd means it divides none)":""}. ${pc(b.tu,b.tn)} go up${b.base===2?"; the exact share is 17/24 = 70.8% (Hasse)":"; the exact share is 2/3"}. Some columns go one way only. Up only: ${pure1.length?pure1.join(", "):"none"}. Down only: ${pure0.length?pure0.join(", "):"none"}. Mixed: ${mix.length?lst(mix):"none"}. The rule behind it: if ${b.base} is not a square modulo p, the period is even, and whether ${b.base} is a square depends only on p mod ${b.base===2?8:40}. If ${b.base} is a square and p ≡ 3 (mod 4), the period divides (p − 1)/2, an odd number, so it is odd. Only the primes ≡ 1 (mod 4) for which ${b.base} is a square are left open, and no remainder settles those: a larger modulus splits the mixed columns again and again. `+(L==="per10"?`This is how one formula beat two puzzle records: a prime ≡ 17 (mod 40) always has an even period.`:`For the Mersenne numbers the same rule says which primes can divide a number 2^n + 1 at all.`)};}
 if((L==="pow2"||L==="riesel"||L==="primorial")&&o.bt){const b=o.bt,R=b.R,rowN=(sg,i)=>b.cells.filter(c=>c.sg===sg&&c.i===i).map(c=>c.n),sum=a=>Array.from(a).reduce((x,y)=>x+y,0),tp=sum(b.prd[0])+sum(b.prd[1]),xs=[],ys=[];for(let sd=0;sd<2;sd++)for(let i=1;i<=R;i++){xs.push(b.prd[sd][i]);ys.push(b.cnt[sd][i]);}
  const mx=xs.reduce((u,v)=>u+v,0)/xs.length,my=ys.reduce((u,v)=>u+v,0)/ys.length;let cxx=0,cyy=0,cxy=0;for(let i=0;i<xs.length;i++){cxx+=(xs[i]-mx)**2;cyy+=(ys[i]-my)**2;cxy+=(xs[i]-mx)*(ys[i]-my);}const cor=cxy/Math.sqrt(cxx*cyy),rows=[];for(let sd=0;sd<2;sd++)for(let i=1;i<=R;i++)rows.push({sd,d:2*i-1,c:b.cnt[sd][i]});
  const sgn=r=>r.sd?"−":"+",nmr=r=>L==="riesel"?`${r.d}·2^n ${sgn(r)} 1`:L==="primorial"?`p# ${sgn(r)} ${r.d}`:`2^n ${sgn(r)} ${r.d}`,rich=rows.slice().sort((x,y)=>y.c-x.c).slice(0,4).map(r=>`${nmr(r)}: ${r.c}`).join(", "),empty=rows.filter(r=>r.c===0),tail=`A sieve by the primes up to 2,000 and then a coin (a survivor near x is prime with chance e^γ·ln 2,000 / ln x, the rule of our gap model) expects ${f(tp)} dots; there are ${f(b.tot)}, and row by row the expected and the found counts have correlation ${cor.toFixed(2)}. Dots beyond the first columns are probable primes (they pass Fermat's test to the bases 3 and 5); ${f(b.done)} numbers were tested.`;
  if(L==="pow2"){const c7=b.cls(7,-1),c1=rowN(-1,1),f1=rowN(1,1),r7=rowN(-1,4),r7p=rowN(1,4);return {pow2:`The exponents are the line here. Column n is the neighbourhood of 2^n, for n = 1 to ${b.Lc}: above the line stand the primes 2^n + d and below it the primes 2^n − d, one row for each odd d from 1 to ${2*R-1}. The columns are spaced by ln n: a number near 2^n is prime about once in n·ln 2 times, so on this scale every row is filled evenly from left to right, each with its own density. Only primes get a dot, ${f(b.tot)} in all. The first row below the line (green) is 2^n − 1: its dots are the Mersenne exponents ${c1.join(", ")}. The first row above is 2^n + 1, prime only for n = ${f1.join(", ")} (Fermat). Each row is thinned in its own rhythm: a prime q divides 2^n ± d for one remainder of n modulo the period of 1/q in base 2 (3 strikes every 2nd n, 7 every 3rd, 5 every 4th, 31 every 5th), so the primes with short periods, the factors of the small Mersenne numbers, decide how full a row is. Fullest rows: ${rich}. ${empty.length?`Rows with no prime at all up to n = ${b.Lc}: ${empty.slice(0,10).map(nmr).join(", ")}${empty.length>10?", …":""}. `:""}The row 2^n − 7 is the puzzle about 2^n − 7: of the 60 remainders of n mod 60 only ${c7} survive 3, 5, 7, 11 and 13, and the row holds ${r7.length?"n = "+r7.join(", "):"no prime"} here (2^n + 7: ${r7p.length?"n = "+r7p.join(", "):"none"}). For 2^n − 1 the rhythm removes every composite n, since each 2^m − 1 with m > 1 (except m = 6) brings a new prime that then divides every 2^n − 1 with m | n (Zsigmondy). `+tail};}
  if(L==="riesel"){const c1=rowN(-1,1),f1=rowN(1,1),eu=empty.filter(r=>!r.sd).map(r=>r.d),ed=empty.filter(r=>r.sd).map(r=>r.d);return {riesel:`The exponents are the line. Column n holds the numbers k·2^n ± 1 for n = 1 to ${b.Lc}: above the line the primes k·2^n + 1 (Proth), below it the primes k·2^n − 1 (Riesel), one row for each odd k from 1 to ${2*R-1}, with the columns spaced by ln n; ${f(b.tot)} dots. The first row below (green, k = 1) is 2^n − 1 with the Mersenne exponents ${c1.join(", ")}; the first row above is 2^n + 1 (n = ${f1.join(", ")}). A prime q divides k·2^n ± 1 for one remainder of n modulo the period of 1/q in base 2, so every row is struck in a fixed rhythm, and a few rows are struck almost everywhere. Rows with no prime up to n = ${b.Lc}: above k = ${eu.length?eu.join(", "):"none"}; below k = ${ed.length?ed.join(", "):"none"}. For some k the strikes cover every n (a covering set): k = 78,557 above (Selfridge) and k = 509,203 below (Riesel) never give a prime. Fullest rows: ${rich}. `+tail};}
  const fu=b.first[0].slice(0,24),comp=b.cells.filter(c=>c.i>1&&c.n>4&&(()=>{const d=c.d;for(let q=3;q*q<=d;q+=2)if(d%q===0)return true;return false;})()).length,p1=rowN(1,1).map(n=>b.pl[n-1]),m1=rowN(-1,1).map(n=>b.pl[n-1]);
  return {primorial:`The same picture around the primorials. Column n is the neighbourhood of p# = 2·3·5·…·p for the n-th prime p, n = 1 to ${b.Lc}: above the line the primes p# + d, below it the primes p# − d, for odd d up to ${2*R-1}; ${f(b.tot)} dots. The empty wedge is the shadow of the primorial: p# ± d shares a factor with d whenever d has a prime factor up to p, so between d = 1 and d = p nothing can be prime. The first dot beyond the wedge is Fortune's number: 3, 5, 7, 13, 23, 17, 19, 23, 37, 61, … (here: ${fu.filter(v=>v).slice(0,14).join(", ")}, …). Fortune conjectured they are all prime; in a column the first candidates are the primes after p themselves, and a composite d would need two prime factors above p, so d > p². Dots at a composite distance from the fifth column on: ${comp}. The green rows are p# + 1 (prime for p = ${p1.join(", ")}) and p# − 1 (p = ${m1.join(", ")}). `+tail};}
 if(L==="glue"&&o.gl){const g=o.gl,ks=[];for(let k=3;k<=Math.min(12,g.best+1);k++)ks.push(`${k}: ${f(g.at[k]||0)} (${g.ex[k]<10?g.ex[k].toFixed(1):f(g.ex[k])} expected)`);return {glue:`Blocks to glue. Rows of width ${f(g.W)} (set the width: 30, 210 and 2,310 are the ones to try). A column of primes one below the other is an arithmetic progression with step ${f(g.W)}; green marks every column run of ${g.G} or more. The longest has ${g.best} primes and starts at ${f(g.bs)}. Runs of at least k primes, found and expected: ${ks.join(", ")}. The expectation is the sieve and then a coin: each of the k numbers is prime with chance 1/ln n, times a factor per small prime q (a step that q divides lifts q out of the way; any other q must miss k different remainders at once). So a step with many small factors gives long runs, and that is the trick behind several puzzle records: with floor and mod a formula can jump from one such block to the next.`};}
 if(L==="stairs"&&o.sr){const r=o.sr,ks=[];for(let k=2;k<=Math.min(12,r.best);k++)ks.push(`${k}: ${f(r.real[k])} against ${f(r.shf[k])}`);return {stairs:`The gaps as a seismogram: the ${f(r.m)} primes in order, 1,000 per band, each at the height of the gap that follows it. Green marks every stretch where the gap grows at least five times in a row. The longest staircase here has ${r.best} rising steps: after ${f(r.start)} the gaps are ${r.gaps.join(", ")}. Rising runs are more common than chance. Runs of k rising steps, in the primes against the same gaps shuffled inside blocks of 1,000: ${ks.join("; ")}. A staircase 2, 4, 6, … is a run of consecutive primes on one parabola n² + n + A (an Euler–Rodriguez chain). The surplus is not a memory of the primes: our sieve-then-coin model of the gaps shows the same surplus, so it comes from the remainders modulo the small primes.`};}
 if(L==="shield"&&o.sd){const d=o.sd;return {shield:`A sieve that needs no division at all. Take the gaps between consecutive primes from the smallest size up. For each size, go from left to right and remove both primes of every pair with that gap, if both are still there. A prime whose two neighbours were taken earlier is shielded and stays for ever: those are green. ${f(d.sv)} of the ${f(d.m)} primes stay, ${pc(d.sv,d.m)}; the conjecture is 1/e² = 13.5%. It is a classic of chemistry in disguise: pairs landing on a line and blocking their neighbours (Flory, 1939), where exactly 1/e² of the sites stay empty when the order is random. Here ${(100*d.sv/d.m).toFixed(2)}% stay, and with the same gaps in a shuffled order ${(100*d.sv2/d.m).toFixed(2)}%. Of the ${d.ee} exponents up to N, ${d.es.length} are shielded (${(d.ee*d.sv/d.m).toFixed(1)} expected)${d.es.length?": "+d.es.map(f).join(", "):""}.`};}
 if(L==="lucky"&&o.lk){const k=o.lk,exp=k.nl*k.m/(S.N/2),exp2=k.l1*k.p1/(S.N/6);return {lucky:`A second sieve next to the primes. The lucky numbers come from a sieve that counts places, not multiples: start with the odd numbers; the second number left is 3, so strike every 3rd number left; the next number left is 7, so strike every 7th; and so on. It never divides, yet it leaves about as many numbers as there are primes: ${f(k.nl)} lucky numbers up to ${NN} against ${f(k.m)} primes. Rows of the chosen width; primes are light and the primes that are also lucky are green: ${f(k.lp)}, where two unrelated sets of these sizes among the odd numbers would share about ${f(exp)}. The shortfall is one remainder: the first strike leaves only numbers ≡ 1 or 3 (mod 6), so about half of the lucky numbers are multiples of 3 and every lucky prime after 3 is ≡ 1 (mod 6). Counted inside that class, unrelated sets would share about ${f(exp2)}. The longest run of consecutive primes with no lucky one has ${k.bu} primes and starts at ${f(k.bus)}; the longest run of consecutive lucky primes has ${k.bl} and starts at ${f(k.bls)}. Of the ${k.ee} exponents up to N, ${k.e1} are ≡ 1 (mod 6) and ${k.el.length} are lucky: ${k.el.map(f).join(", ")} (3 and about ${k.xe.toFixed(1)} more expected from the density of lucky numbers near each exponent).`};}
 if(o.sh&&o.sh.kind===L){const h=o.sh,T={
  galaxy:()=>`A galaxy: the number n lies at distance √n from the centre, on the arm of its remainder mod ${h.P} (the period P; try 30 or 210), and the arms wind one and a quarter turns on the way out. Every prime beyond the factors of ${h.P} lies on one of ${h.arms} of the ${h.P} arms; the other arms stay dark. It is the wheel layout with a twist, so a bright arm and a dark arm can be followed by eye from the centre to the rim.`,
  globe:()=>`A globe, seen from the front (left) and from behind (right). The numbers run from the north pole to the south pole, each on the meridian of its remainder mod ${h.P} (the period P; try 30 or 210), spaced so that every band of latitude holds equally many numbers. The primes sit on a few meridians only; they thin out towards the south, where the numbers are larger.`,
  donut:()=>`A ring. The numbers go once around the ring, and each sits on the tube at the angle of its remainder mod ${h.P} (the period P; try 30 or 210). Each remainder is one band that runs around the ring; the bands of the primes are the bright ones, and they fade along the ring as the numbers grow.`,
  crystal:()=>`A crystal seen at an angle: the numbers fill a cube, ${h.sd} in a row, ${h.sd} rows in a layer, layer on layer. The side is a multiple of 6, so the primes can only stand in ${h.lit} of the ${h.sd} upright sheets (the remainders mod ${h.sd} with no factor in common with it), and from this angle the sheets show as slanted stripes with empty gaps between them. A line of sight through the cube strings together numbers with a fixed step.`,
  dragon:()=>`The dragon curve: a strip of paper folded in half again and again and opened to right angles. The number n is the n-th piece of the strip; after it the strip turns left or right as the paper-folding rule says (read n in binary: the bit above its lowest 1 decides). The pieces alternate between the two diagonals of this picture, so every odd number, and with it every prime after 2, lies on pieces of one slope: primes on pieces pointing right ${f(h.dc[0])}, up ${f(h.dc[1])}, left ${f(h.dc[2])}, down ${f(h.dc[3])}.`,
  gosper:()=>`The flowsnake (Gosper's curve): one line that fills a hexagonal island made of seven smaller islands, each made of seven again, ${h.D} levels deep; ${NN} of its ${f(7**h.D)} steps are drawn. The digits of n in base 7 say in which island of each level it lies, so the multiples of 7 are the points where one smallest island ends and the next begins.`,
  fan:()=>`A fan. Write n as a rectangle a × b that is as square as possible (a the largest divisor up to √n). The number lies at distance √n from the corner; its angle is 0 for a rectangle 1 × n and a quarter turn for a square. So the primes lie on the bottom edge, the squares on the left edge, and every other number between them by how square it can be made: the curves just above the primes are 2p, 3p, 4p, …. ${f(h.hi)} numbers lie in the upper half of the fan (a ≥ the fourth root of n).`,
  bubbles:()=>`Primes on a line, the others in bubbles. The ${f(h.m)} primes lie at equal steps along one spiral. The numbers between a prime and the next form a loop that starts and ends at the prime, so the size of a bubble is the gap. Twin primes have the smallest bubbles (${f(h.tw)} of them); the largest belongs to the gap of ${h.mg} after ${f(h.ms)}. Large bubbles come more and more often towards the rim; zoom in to see single bubbles.`,
  daisy:()=>`A daisy with one petal for each remainder mod ${h.P} (the period P; try 30): the number n lies in the petal of its remainder, further out the larger it is. Every prime beyond the factors of ${h.P} lies in one of ${h.arms} petals; the others stay dark.`,
  mobius:()=>`A Möbius band: the numbers go once around, each in the lane of its remainder mod ${h.P} across the band (the period P; try 30). The band has a half twist, so after one round the lane of the remainder r meets the lane of −r. A remainder and its negative hold primes together or not at all, so bright meets bright.`,
  canopy:()=>`A tree. Read n in binary after its first 1: every 0 bends the branch to the left, every 1 to the right, and each branch is three quarters of the one before. Numbers that start with the same bits share a bough. An odd number ends on a right turn, so the primes sit on the right-hand twig of every last fork.`,
  disc:()=>`Plain rows, cut to a disc: every row is centred and as long as the circle allows (radius ${f(h.R)}). The rows no longer line up, so columns turn into arcs: a remainder that would be a straight lane in a square bends into curves, and the picture shows which lanes survive the bending.`,
  heart:()=>`Plain rows inside a heart: the numbers fill the shape row by row from the top, both lobes in one sweep. As in the disc, the changing row length bends every lane into curves.`,
  fibsquares:()=>`The golden spiral of squares: squares with sides ${h.sq.slice(0,9).join(", ")}, … up to ${f(h.sq[h.sq.length-1])}, each set against the long side of the rectangle built so far. Every square is filled in rows of its own side, so it shows the primes in rows of a Fibonacci width; a width such as 144 = 2⁴·3² leaves the primes only 48 of its 144 columns, a prime width such as 233 leaves them every column.`,
  dna:()=>`A double helix. Every prime after 3 is one less or one more than a multiple of 6, so the numbers 6k − 1 run along one strand and 6k + 1 along the other; 6k is the middle of the rung between them and the three numbers 6k + 2, 6k + 3, 6k + 4 fill the space to the next rung. A rung with two light ends is a pair of twin primes: ${f(h.tw[0])} rungs have both ends prime, ${f(h.tw[1])} one and ${f(h.tw[2])} none.`,
  popcorn:()=>`Every fraction between 0 and 1, once. The n-th fraction of Stern's sequence a/b is drawn at a/(a + b) from left to right and lower the larger a + b is (down to ${f(h.md)}). The gaps are the famous ones: near a simple fraction such as 1/2 or 1/3 there is no room for other simple fractions. An odd n above 1 gives a fraction above 1/2, so the primes fill the right half.`,
  terdragon:()=>`The terdragon: a curve of unit steps that turns by a third of a turn, left or right as the last digit of n in base 3 that is not 0 says (1 left, 2 right). It never runs along the same piece twice. The pieces point in three directions, and the primes are spread unevenly over them: ${h.dc.map(f).join(", ")}. The direction of piece n is the number of digits 1 in n − 1, written in base 3, taken mod 3. For an odd n that number is even, and with this many digits an even count is most often 4: the middle direction.`,
  nautilus:()=>`A nautilus shell. Each chamber holds the numbers from one power of two to the next, twice as many as the chamber before, and six chambers make a full turn. A number and its double sit at the same place in neighbouring chambers, so the dots of p, 2p, 4p, … spiral outwards, and only the first of them is light.`,
  twindragon:()=>`The twin dragon. Write n in binary and read the digits as powers of −1 + i instead of powers of 2: every point of the square grid is reached exactly once, and the numbers up to ${NN} fill this fractal tile. An odd n lands on a point whose two coordinates add up to an odd number, so the primes stand on one colour of a chessboard.`,
  fivedragon:()=>`The same idea in base 5: the digits of n in base 5 are read as powers of −2 + i. Again every grid point is reached exactly once. The last digit of n decides one of five interleaved grids, and the grid of the digit 0 holds no prime but 5.`,
  hexaflake:()=>`A hexagon of seven hexagons, each again of seven. The last digit of n in base 7 picks the large hexagon (0 the centre), the digit before it the hexagon inside that, and so on. The multiples of 7 fill the centre hexagon, so it holds no prime but 7; the other six look alike.`,
  pentaflake:()=>`Five pentagons around a sixth, each again made of six. The last digit of n in base 6 picks the large pentagon (0 the centre). Primes can only end in 1 or 5 in base 6, so two of the six large pentagons hold every prime after 3.`,
  carpet:()=>`Sierpinski's carpet: eight squares around a hole, each again eight squares. The last digit of n in base 8 picks the large square, the digit before it the next level. The even digits give four squares without primes; the four odd ones hold them all, and inside each the pattern repeats without preference.`,
  vicsek:()=>`A cross of five squares, each again a cross. The last digit of n in base 5 picks the arm (0 the centre). The centre holds the multiples of 5 and so no prime but 5.`,
  levy:()=>`Lévy's C curve on the square grid: step n points east, north, west or south as the number of 1s in the binary form of n says (mod 4). Unlike the dragon it runs over the same pieces many times, so many numbers share a place and only the last one shows.`,
  fibword:()=>`The Fibonacci word fractal: go one step for every letter of the Fibonacci word 0100101001001…; after a letter 0 turn left if its place n is even and right if it is odd. The curve never crosses itself and is built from the Fibonacci numbers: every stretch of F(k) steps repeats the shape of an earlier one.`,
  collatz:()=>`The Collatz seaweed. From each n follow the rule (halve an even number, send an odd one to 3n + 1) down to 1, then draw the path backwards from the root: one step per number, bending left at an even number and right at an odd one. The dot of n is the tip of its own path. Numbers whose paths join early share a stem.`,
  sunrays:()=>`Six suns. The primes stand on six circles in order, and the numbers up to the next prime run outwards from each prime as a ray, so the length of a ray is the gap.`,
  cone:()=>`A cone, apex at the top. The numbers wind down from the apex, each on the straight line of its remainder mod ${h.P} (the period P; try 30), so the lanes of the wheel become the lines from the apex to the rim.`,
  vase:()=>`A vase. The numbers run from the foot to the lip, each on the meridian of its remainder mod ${h.P} (the period P; try 30). Where the vase is narrow the meridians crowd together.`,
  trefoil:()=>`A band tied into a trefoil knot. The numbers go once along the knot, each in the lane of its remainder mod ${h.P} across the band (the period P; try 30), and the band turns over one and a half times on the way.`,
  starrows:()=>`Plain rows inside a five-pointed star. Each row is as long as the star allows, so a lane of the rows is cut and shifted at every row; lanes turn into fans in the points and into arcs in the body.`,
  moon:()=>`Plain rows inside a crescent. The rows are short at the horns and long in the belly, and their left ends follow a circle: every lane bends.`,
  letterm:()=>`Plain rows inside the letter M, for Mersenne. In the two legs the rows have a fixed length, so lanes stay straight there; in the slanted strokes they shear.`,
  yinyang:()=>`Yin and yang. The first half of the numbers fills one half in rows, the second half the other, so the two halves show the same rows at two sizes of number: the half with the larger numbers is a little thinner in primes.`,
  ringrows:()=>`Plain rows inside a ring. Above and below the hole the rows are whole; beside it each row is two short pieces, so lanes break and start again.`,
  wheels:()=>`Wheels within wheels: the sieve drawn as it works. The remainder of n mod 2 picks one of two discs, its remainder mod 3 one of three inside that, then mod 5, mod 7 and mod 11. The 2,310 small discs are the remainders mod 2,310, and each holds the numbers with that remainder. At every level one place is the remainder 0, and nothing prime can live there, so only 480 of the 2,310 discs hold primes.`,
  fishbone:()=>`A fishbone: the primes are the spine, in order from left to right in bands, and the numbers up to the next prime are a rib, by turns up and down. The length of a rib is the gap.`,
  tuned:()=>`The layout a search found. A scorer measures, for every pair of neighbouring cells, how much one cell tells about the other being prime, and adds this up over the 24 nearest directions. A search over 537 generated maps (rows, spirals, turns by a fixed angle, between-squares maps, sheared cubes) in three rounds ended here: a cube of side 30, laid out flat with every layer shifted two cells left and one down. It scores 565 thousandths of a bit, plain rows 198, rows of width 210 score 275. Decoys made by a sieve and a coin score 562 on the same map: the search made the sieve as visible as it can be and found nothing else. The 15 maps that looked best for something beyond the sieve lost all of it on numbers they had not seen.`,
  fermat:()=>`What the sieve leaves, between the squares. Row r holds the numbers from r² to (r + 1)² − 1, and only the numbers with no prime factor up to ${h.y0} (N to the power 0.4027) are drawn: ${f(h.ns)} of them. The primes are dark here; the ${f(h.nc)} green ones are the composites that are left, each a product of two primes above ${h.y0}. Our gap model treats green against dark as a coin flip. Here it is not one: every green number is a difference of two squares, t² − s² = (t − s)(t + s), and when its two factors are close, t is only a little above √n. With t = r + j the number sits at column 2jr + j² − s², so the green dots with the same j and s form a straight line across the rows: slope 2 for j = 1 (parallel to the right edge, at the distances s² from it), slope 4 for j = 2, and so on. Green dots by j, from 1 to 10: ${h.jc.slice(1,11).map(f).join(", ")}; larger: ${f(h.jc[11])}. The lines are too thin to see by eye, but they count: for pairs of numbers whose distance is tied to √n, sieve-and-coin is off by about 1%. A separate count up to 20 million shows the cause: take out only the green numbers with j = 1 (2.4% of them) and the error falls from 0.47% to 0.17%, the level of the noise. The primes themselves follow Hardy and Littlewood exactly; it is the model of them that is too simple here.`,
  record:()=>`A record. The numbers are written on a tape ${h.P} wide (the period P; try 30) that is wound into a spiral, so each remainder mod ${h.P} is a groove. The grooves of the primes are bright; next to each other in a groove sit numbers ${h.P} apart.`,
  target:()=>`A target: one ring for every remainder mod ${h.P} (the period P; try 30), and inside its ring a remainder's numbers run round and round. Whole rings are bright or dark.`,
  rainbow:()=>`A rainbow: one band for every remainder mod ${h.P} (the period P; try 30), its numbers running from left to right in a few arcs. Bright and dark bands are the remainders with and without primes.`,
  mosaic:()=>`A mosaic: one tile for every remainder mod ${h.P} (the period P; try 30 or 210), each tile filled in rows with the numbers of that remainder. Most tiles are dark; inside a bright tile the next primes draw their own stripes.`,
  classbands:()=>`One band for every remainder mod ${h.P} (the period P; try 30), each filled column by column with its numbers. A bright band is a remainder that primes can have; inside it the dots thin out to the right as the numbers grow.`,
  hourglass:()=>`An hourglass: two cones tip to tip. The numbers run from the top rim through the waist to the bottom rim, each on the line of its remainder mod ${h.P} (the period P; try 30), so every lane crosses the waist.`,
  accordion:()=>`Plain rows of width ${f(h.W||0)} (set the width) on a sheet folded like an accordion and seen from the side. A straight lane of the rows becomes a zigzag over the folds.`,
  pinwheel:()=>`A pinwheel: one curved blade for every remainder mod ${h.P} (the period P; try 30), the numbers moving outwards along it.`,
  helicoid:()=>`A spiral staircase seen from the side: the numbers climb four turns, each at the distance from the axis that belongs to its remainder mod ${h.P} (the period P; try 30). Every remainder is its own helix, nested inside the others.`,
  curlicue:()=>`A curlicue: a walk of unit steps in which the heading turns faster and faster; step n points in the direction n²·ψ with ψ = 360° / (${h.P} + 0.618…) (the period P changes the figure). The shape has nothing to do with primes, and that is its use: it is a neutral thread on which the primes are scattered, to compare with the layouts where they line up.`,
  road:()=>`A road to the horizon: plain rows of width ${f(h.W)} (set the width), laid flat and seen in perspective, small numbers at the front. Columns become rays to the vanishing point, so a column rich in primes shows as a bright ray, and a diagonal of the rows as a curve. With a width of 30 or 210 the rays are the lanes of the wheel.`};
  if(T[L])return {[L]:T[L]()};}
 return {};}
